patterns-on-this-page--article.snippet:
import { Component } from '@angular/core';
import { OnThisPageLinkComponent } from './on-this-page-link.component';

@Component({
  selector: 'app-demo',
  imports: [OnThisPageLinkComponent],
  template: `
    <div
        style="display: grid; grid-template-columns: 240px minmax(0, 60ch); gap: var(--space-48)">
        <nav dma-on-this-page>
            @for (section of sections; track section.id) {
            <li>
                <a
                    dma-on-this-page-link
                    [href]="'#' + section.id">
                    {{ section.heading }}
                </a>
            </li>
            }
        </nav>
        <article>
            @for (section of sections; track section.id) {
            <h2 [id]="section.id">{{ section.heading }}</h2>
            @for (paragraph of paragraphs; track paragraph) {
            <p>
                A paragraph of {{ section.heading }}. The article runs long enough that the page scrolls
                                    past each of its sections, so the mark in the nav follows the reader down the page.
            </p>
            }
                        }
        </article>
    </div>`,
})
export class DemoComponent {}
